/* Per-product Open Graph card (1200×630) for /merch/[slug], generated by
   Next's built-in ImageResponse. Same brand field as the site-wide card in
   src/app/opengraph-image.tsx, with the product name, its price and the
   pre-launch caveat, so a shared merch link is not mistaken for a shop that
   already charges. No twitter-image: Next falls back to this one.

   Satori constraints apply — flexbox only, explicit `display: 'flex'` on every
   container, and only the Latin Noto Sans that @vercel/og bundles. The ✦ in
   the catalogue names is outside that font's coverage, so it is stripped here
   rather than rendered as tofu. */

import { notFound } from 'next/navigation';
import { ImageResponse } from 'next/og';

import { MERCH_ORDER, PRODUCT_COPY, isMerchSlug } from './product-copy';

export const runtime = 'nodejs';

export const size = { width: 1200, height: 630 };
export const contentType = 'image/png';

const BLUE = '#0047BA';
const PAPER = '#FAFAF8';
const ORANGE = '#F05627';

/* Mirrors MERCH[slug].price in src/components/notiva/basket-context.tsx.
   Duplicated deliberately: that module is a client component, so importing its
   values into a server-rendered image route would yield client references
   rather than the numbers. Prices are EUR, incl. VAT. */
const PRICE: Record<(typeof MERCH_ORDER)[number], number> = {
	shirt: 29,
	hoodie: 59,
	cap: 24,
	tote: 19,
	pin: 9,
	stickers: 6,
	sleeve: 34,
	plush: 39,
};

/* public/notiva/notiva-logo-chip.svg, inverted for the blue field. */
const CHIP = `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="600" viewBox="0 0 600 600"><rect width="600" height="600" rx="136" fill="${PAPER}"/><path d="M424.407 407.759V270.761C424.407 265.961 421.598 261.605 417.228 259.628L248.372 183.094C244.196 181.2 239.306 181.803 235.713 184.661L179.613 229.282C176.699 231.599 175 235.122 175 238.847V397.785C175 408.605 188.019 414.092 195.76 406.531L248.552 355.002C252.166 351.471 257.576 350.535 262.175 352.63L407.094 418.878C415.189 422.582 424.4 416.665 424.4 407.759H424.407Z" fill="${BLUE}"/><path d="M424.407 236.544V200.816C424.407 189.322 415.085 180 403.591 180H305.533" fill="${BLUE}"/></svg>`;

const CHIP_SRC = `data:image/svg+xml;base64,${Buffer.from(CHIP).toString('base64')}`;

export function generateStaticParams(): { slug: string }[] {
	return MERCH_ORDER.map((slug) => ({ slug }));
}

export async function generateImageMetadata({
	params,
}: {
	params: Promise<{ slug: string }>;
}): Promise<{ id: string; size: typeof size; contentType: string; alt: string }[]> {
	const { slug } = await params;
	const name = isMerchSlug(slug) ? plain(PRODUCT_COPY[slug].name.de) : 'Merch';
	return [
		{
			id: slug,
			size,
			contentType,
			alt: `${name} aus dem Notiva-Shop — Vorbestellung, unverbindlich bis zum Launch.`,
		},
	];
}

/** The catalogue names carry a ✦ the bundled font cannot draw. */
function plain(name: string): string {
	return name.replace(/✦/g, '').replace(/\s+/g, ' ').trim();
}

export default async function MerchOpengraphImage({
	params,
}: {
	params: Promise<{ slug: string }>;
}) {
	const { slug } = await params;
	if (!isMerchSlug(slug)) notFound();

	const name = plain(PRODUCT_COPY[slug].name.de);
	const price = PRICE[slug];

	return new ImageResponse(
		(
			<div
				style={{
					width: '100%',
					height: '100%',
					display: 'flex',
					flexDirection: 'column',
					justifyContent: 'space-between',
					padding: '72px 80px',
					backgroundColor: BLUE,
					backgroundImage:
						'radial-gradient(1000px 620px at 88% -8%, rgba(240,86,39,0.34), rgba(240,86,39,0) 62%)',
					color: PAPER,
					fontFamily: '"Noto Sans"',
				}}
			>
				{/* header */}
				<div
					style={{
						display: 'flex',
						alignItems: 'center',
						justifyContent: 'space-between',
					}}
				>
					<div style={{ display: 'flex', alignItems: 'center' }}>
						<img src={CHIP_SRC} width={68} height={68} alt="" />
						<div
							style={{
								marginLeft: 22,
								fontSize: 38,
								letterSpacing: 12,
								WebkitTextStroke: `1.2px ${PAPER}`,
							}}
						>
							NOTIVA
						</div>
					</div>
					<div
						style={{
							fontSize: 26,
							letterSpacing: 4,
							color: 'rgba(250,250,248,0.82)',
						}}
					>
						SHOP
					</div>
				</div>

				{/* product */}
				<div style={{ display: 'flex', flexDirection: 'column' }}>
					<div
						style={{
							display: 'flex',
							width: 104,
							height: 10,
							borderRadius: 5,
							backgroundColor: ORANGE,
							marginBottom: 28,
						}}
					/>
					<div
						style={{
							display: 'flex',
							fontSize: 82,
							lineHeight: 1.1,
							letterSpacing: -2,
							WebkitTextStroke: `1.6px ${PAPER}`,
						}}
					>
						{name}
					</div>
					<div
						style={{
							marginTop: 20,
							fontSize: 30,
							color: 'rgba(250,250,248,0.78)',
						}}
					>
						{PRODUCT_COPY[slug].material.de}
					</div>
					<div
						style={{
							display: 'flex',
							alignItems: 'center',
							marginTop: 28,
						}}
					>
						<div
							style={{
								display: 'flex',
								alignItems: 'center',
								padding: '10px 26px',
								borderRadius: 999,
								backgroundColor: ORANGE,
								fontSize: 34,
								WebkitTextStroke: `0.8px ${PAPER}`,
							}}
						>
							{`€${price}`}
						</div>
						<div
							style={{
								marginLeft: 24,
								fontSize: 29,
								color: 'rgba(250,250,248,0.82)',
							}}
						>
							Vorbestellung — unverbindlich bis zum Launch
						</div>
					</div>
				</div>

				{/* footer */}
				<div
					style={{
						display: 'flex',
						alignItems: 'center',
						justifyContent: 'space-between',
					}}
				>
					<div
						style={{
							fontSize: 32,
							letterSpacing: 1,
							WebkitTextStroke: `0.8px ${PAPER}`,
						}}
					>
						{`notiva.de/merch/${slug}`}
					</div>
					<div
						style={{
							fontSize: 26,
							color: 'rgba(250,250,248,0.72)',
						}}
					>
						Versand frei ab €60
					</div>
				</div>
			</div>
		),
		{ ...size },
	);
}
